/** Each event the Go side sends, and what it carries. */
interface BackendEvents {
    "navigate": string;
    "refresh": void;
    "hideAmounts": void;
    "palette": void;
    "progress": install.Event;
    "link": wiring.Link;
    "install:log": string;
    "setup:log": string;
    "cli:log": string;
    "cli:step": ui.StepEvent;
    "job:app": progress.Update;
    "status:changed": engine.Change;
    "status:card": board.Card;
    "app:update": app.PendingUpdate | null;
    "app:download": app.Download;
    "update:state": app.UpdateState;
    "update:step": app.UpdateStep;
    "media:event": Record<string, unknown>;
}
